  foreach ($p in $paths) {
    if (-not (Test-Path -LiteralPath $p -ErrorAction Stop)) { continue }
    $properties = Microsoft.PowerShell.Management\Get-ItemProperty -LiteralPath $p -ErrorAction Stop
